void ServiceManagerAsyncWaiter::Query(
    const std::string& service_name, ErrorOrServiceStatePtr* out_result) {
  base::RunLoop loop;
  proxy_->Query(std::move(service_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             ErrorOrServiceStatePtr* out_result
,
             ErrorOrServiceStatePtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}



